// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessedHash, address caller) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 3 ether);

        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessedHash);

        vm.roll(block.number + 2);

        uint256 balBefore = address(c).balance;

        vm.prank(caller);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        uint256 storedBlock = block.number - 1;
        bytes32 answer = blockhash(storedBlock);

        bool matched = (guessedHash == answer);
        if (matched) {
            assertTrue(balBefore == balAfter + 2 ether);
        } else {
            assertTrue(balBefore == balAfter);
        }
    }
}
